```javascript
const { Client, Collection, Intents, SlashCommandBuilder } = require('discord.js');
const { token } = require('./config.json');

const client = new Client({ intents: [Intents.FLAGS.GUILDS, Intents.FLAGS.GUILD_MESSAGES] });

client.commands = new Collection();

const banCommand = new SlashCommandBuilder()
  .setName('ban')
  .setDescription('Ban a user from the server')
  .addUserOption((option) =>
    option
      .setName('user')
      .setDescription('The user to ban')
      .setRequired(true)
  );

client.on('ready', () => {
  console.log(`Logged in as ${client.user.tag}!`);
  client.commands.set(banCommand.toJSON(), banCommand);
});

client.on('interactionCreate', async (interaction) => {
  if (!interaction.isChatInputCommand()) return;

  const command = interaction.client.commands.get(interaction.commandName);

  if (!command) return;

  try {
    await command.execute(interaction);
  } catch (error) {
    console.error(error);
    await interaction.reply({ content: 'There was an error while executing this command!', ephemeral: true });
  }
});

client.login(token);

client.commands.get('ban').execute = async (interaction) => {
  const user = interaction.options.getUser('user');

  if (!user) return interaction.reply({ content: 'Please provide a user to ban!', ephemeral: true });

  try {
    await interaction.guild.members.ban(user, { reason: 'Banned by the bot' });
    await interaction.reply({ content: `Successfully banned ${user.tag}!`, ephemeral: true });
  } catch (error) {
    console.error(error);
    await interaction.reply({ content: 'There was an error while banning the user!', ephemeral: true });
  }
};
```

